/** Скопировать номер карты в буфер (с fallback для старых браузеров) */ function copyCardNumber() {
    const done = ()=>{
        try {
            if (navigator.clipboard?.writeText) {
                void navigator.clipboard.writeText(AUTHOR_CARD_RAW);
                return;
            }
        } catch  {
        /* переходим к fallback */ }
        try {
            const ta = document.createElement('textarea');
            ta.value = AUTHOR_CARD_RAW;
            ta.style.position = 'fixed';
            ta.style.opacity = '0';
            document.body.appendChild(ta);
            ta.select();
            document.execCommand('copy');
            document.body.removeChild(ta);
        } catch  {
        /* совсем без буфера — ничего не делаем */ }
    };
    done();
}
